import React, { useState, useEffect, useRef } from 'react';
import { useNavigate } from 'react-router-dom';
import monitoringService from '../../api/services/monitoringService';
import socketService from '../../utils/socket';
import { useNotification } from '../../context/notification/NotificationContext';
import Button from '../../components/ui/Button';
import Card from '../../components/ui/Card';
import LoadingSpinner from '../../components/ui/LoadingSpinner';

/**
 * Quick Monitoring Page - Start monitoring without selecting a session
 * Uses a test/demo exam session ID
 */
const QuickMonitoring = () => {
  const navigate = useNavigate();
  const { showNotification } = useNotification();
  
  // Use a test exam session ID
  const [examSessionId, setExamSessionId] = useState('test-session-123');
  const [isMonitoring, setIsMonitoring] = useState(false);
  const [monitoringSessionId, setMonitoringSessionId] = useState(null);
  const [alerts, setAlerts] = useState([]);
  const [systemStatus, setSystemStatus] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [currentFrame, setCurrentFrame] = useState(null);
  
  const monitoringSocketRef = useRef(null);

  useEffect(() => {
    // Connect to monitoring socket
    monitoringSocketRef.current = socketService.joinMonitoring();

    // Set up event listeners
    monitoringSocketRef.current.on('video_frame', handleVideoFrame);
    monitoringSocketRef.current.on('monitoring_alert', handleAlert);
    monitoringSocketRef.current.on('monitoring_status', handleStatus);
    monitoringSocketRef.current.on('monitoring_error', handleError);
    monitoringSocketRef.current.on('monitoring_stopped', handleStopped);

    return () => {
      // Cleanup
      if (monitoringSocketRef.current) {
        monitoringSocketRef.current.off('video_frame', handleVideoFrame);
        monitoringSocketRef.current.off('monitoring_alert', handleAlert);
        monitoringSocketRef.current.off('monitoring_status', handleStatus);
        monitoringSocketRef.current.off('monitoring_error', handleError);
        monitoringSocketRef.current.off('monitoring_stopped', handleStopped);
        monitoringSocketRef.current.disconnect();
      }
    };
  }, []);

  const handleVideoFrame = (data) => {
    setCurrentFrame(`data:image/jpeg;base64,${data.frame}`);
  };

  const handleAlert = (data) => {
    const newAlert = {
      id: Date.now(),
      reason: data.reason,
      timestamp: data.timestamp,
      alert_time: data.alert_time,
      filename: data.filename
    };
    
    setAlerts(prev => [newAlert, ...prev]);
    
    showNotification({
      type: 'warning',
      message: `Alert: ${formatAlertReason(data.reason)}`,
      duration: 5000
    });
    
    playAlertSound();
  };

  const handleStatus = (data) => {
    setSystemStatus(data.message);
    console.log('Status:', data.message);
  };

  const handleError = (data) => {
    showNotification({
      type: 'error',
      message: `Monitoring Error: ${data.error}`,
      duration: 5000
    });
  };

  const handleStopped = (data) => {
    setIsMonitoring(false);
    setMonitoringSessionId(null);
    showNotification({
      type: 'info',
      message: `Monitoring stopped: ${data.reason}`,
      duration: 3000
    });
  };

  const startMonitoring = async () => {
    try {
      setIsLoading(true);
      console.log('Starting monitoring for session:', examSessionId);
      
      const response = await monitoringService.startMonitoring(examSessionId);
      console.log('Monitoring response:', response);
      
      setMonitoringSessionId(response.session_id);
      setIsMonitoring(true);
      showNotification({
        type: 'success',
        message: 'Monitoring started successfully',
        duration: 3000
      });
    } catch (error) {
      console.error('Monitoring start error:', error);
      showNotification({
        type: 'error',
        message: error.response?.data?.error || error.message || 'Failed to start monitoring',
        duration: 5000
      });
    } finally {
      setIsLoading(false);
    }
  };

  const stopMonitoring = async () => {
    try {
      setIsLoading(true);
      await monitoringService.stopMonitoring(monitoringSessionId);
      setIsMonitoring(false);
      setMonitoringSessionId(null);
      setCurrentFrame(null);
      showNotification({
        type: 'success',
        message: 'Monitoring stopped',
        duration: 3000
      });
    } catch (error) {
      showNotification({
        type: 'error',
        message: error.response?.data?.error || 'Failed to stop monitoring',
        duration: 5000
      });
    } finally {
      setIsLoading(false);
    }
  };

  const formatAlertReason = (reason) => {
    const reasonMap = {
      'HEAD_LEFT': 'Looking Left',
      'HEAD_RIGHT': 'Looking Right',
      'HAND_MOUTH': 'Hand Near Mouth',
      'PHONE_DETECTED': 'Phone Detected',
      'WATCH_DETECTED': 'Watch Detected',
      'PAPER_PASSING': 'Paper Passing'
    };
    return reasonMap[reason] || reason;
  };

  const getAlertSeverity = (reason) => {
    const highSeverity = ['PHONE_DETECTED', 'PAPER_PASSING'];
    const mediumSeverity = ['WATCH_DETECTED', 'HAND_MOUTH'];
    
    if (highSeverity.includes(reason)) return 'high';
    if (mediumSeverity.includes(reason)) return 'medium';
    return 'low';
  };

  const playAlertSound = () => {
    try {
      const audioContext = new (window.AudioContext || window.webkitAudioContext)();
      const oscillator = audioContext.createOscillator();
      const gainNode = audioContext.createGain();
      
      oscillator.connect(gainNode);
      gainNode.connect(audioContext.destination);
      
      oscillator.frequency.value = 800;
      oscillator.type = 'sine';
      
      gainNode.gain.setValueAtTime(0.3, audioContext.currentTime);
      gainNode.gain.exponentialRampToValueAtTime(0.01, audioContext.currentTime + 0.5);
      
      oscillator.start(audioContext.currentTime);
      oscillator.stop(audioContext.currentTime + 0.5);
    } catch (error) {
      console.error('Audio error:', error);
    }
  };

  return (
    <div className="min-h-screen bg-gray-50 dark:bg-gray-900 p-6">
      <div className="max-w-7xl mx-auto">
        {/* Header */}
        <div className="mb-6">
          <h1 className="text-3xl font-bold text-gray-900 dark:text-white">
            Live Monitoring
          </h1>
          <p className="text-gray-600 dark:text-gray-400 mt-1">
            Start exam monitoring with AI-powered behavior analysis
          </p>
        </div>

        {/* Session ID Input */}
        <Card className="mb-6">
          <div className="p-6">
            <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-2">
              Exam Session ID (optional)
            </label>
            <input
              type="text"
              value={examSessionId}
              onChange={(e) => setExamSessionId(e.target.value)}
              disabled={isMonitoring}
              className="w-full px-4 py-2 border border-gray-300 dark:border-gray-600 rounded-lg bg-white dark:bg-gray-700 text-gray-900 dark:text-white focus:ring-2 focus:ring-blue-500"
              placeholder="Enter exam session ID or use default"
            />
            <p className="text-xs text-gray-500 dark:text-gray-400 mt-1">
              Leave as default for testing
            </p>
          </div>
        </Card>

        {/* Control Panel */}
        <Card className="mb-6">
          <div className="p-6">
            <div className="flex items-center justify-between">
              <div>
                <h2 className="text-xl font-semibold text-gray-900 dark:text-white mb-2">
                  Monitoring Control
                </h2>
                {systemStatus && (
                  <p className="text-sm text-gray-600 dark:text-gray-400">
                    Status: {systemStatus}
                  </p>
                )}
              </div>
              <div className="flex gap-3">
                {!isMonitoring ? (
                  <Button
                    onClick={startMonitoring}
                    disabled={isLoading || !examSessionId}
                    className="bg-green-600 hover:bg-green-700"
                  >
                    {isLoading ? <LoadingSpinner size="sm" /> : 'Start Monitoring'}
                  </Button>
                ) : (
                  <Button
                    onClick={stopMonitoring}
                    disabled={isLoading}
                    className="bg-red-600 hover:bg-red-700"
                  >
                    {isLoading ? <LoadingSpinner size="sm" /> : 'Stop Monitoring'}
                  </Button>
                )}
              </div>
            </div>
            
            {isMonitoring && (
              <div className="mt-4 flex items-center gap-2">
                <div className="w-3 h-3 bg-green-500 rounded-full animate-pulse"></div>
                <span className="text-sm text-green-600 dark:text-green-400 font-medium">
                  Monitoring Active - Session: {monitoringSessionId}
                </span>
              </div>
            )}
          </div>
        </Card>

        <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
          {/* Video Feed */}
          <Card>
            <div className="p-6">
              <h2 className="text-xl font-semibold text-gray-900 dark:text-white mb-4">
                Live Video Feed
              </h2>
              <div className="bg-black rounded-lg overflow-hidden aspect-video flex items-center justify-center">
                {currentFrame ? (
                  <img
                    src={currentFrame}
                    alt="Live monitoring feed"
                    className="w-full h-full object-contain"
                  />
                ) : (
                  <div className="text-gray-500 text-center p-8">
                    <svg
                      className="w-16 h-16 mx-auto mb-2"
                      fill="none"
                      stroke="currentColor"
                      viewBox="0 0 24 24"
                    >
                      <path
                        strokeLinecap="round"
                        strokeLinejoin="round"
                        strokeWidth={2}
                        d="M15 10l4.553-2.276A1 1 0 0121 8.618v6.764a1 1 0 01-1.447.894L15 14M5 18h8a2 2 0 002-2V8a2 2 0 00-2-2H5a2 2 0 00-2 2v8a2 2 0 002 2z"
                      />
                    </svg>
                    <p className="text-sm">
                      {isMonitoring
                        ? 'Waiting for video feed...'
                        : 'Start monitoring to see video feed'}
                    </p>
                    <p className="text-xs mt-2 text-gray-600">
                      Camera permissions required
                    </p>
                  </div>
                )}
              </div>
            </div>
          </Card>

          {/* Alerts Panel */}
          <Card>
            <div className="p-6">
              <h2 className="text-xl font-semibold text-gray-900 dark:text-white mb-4">
                Alerts ({alerts.length})
              </h2>
              <div className="space-y-3 max-h-[500px] overflow-y-auto">
                {alerts.length === 0 ? (
                  <div className="text-center text-gray-500 py-8">
                    <svg
                      className="w-12 h-12 mx-auto mb-2"
                      fill="none"
                      stroke="currentColor"
                      viewBox="0 0 24 24"
                    >
                      <path
                        strokeLinecap="round"
                        strokeLinejoin="round"
                        strokeWidth={2}
                        d="M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z"
                      />
                    </svg>
                    <p>No alerts detected</p>
                  </div>
                ) : (
                  alerts.map((alert) => {
                    const severity = getAlertSeverity(alert.reason);
                    const severityColors = {
                      high: 'bg-red-100 border-red-500 text-red-800 dark:bg-red-900 dark:text-red-200',
                      medium: 'bg-yellow-100 border-yellow-500 text-yellow-800 dark:bg-yellow-900 dark:text-yellow-200',
                      low: 'bg-blue-100 border-blue-500 text-blue-800 dark:bg-blue-900 dark:text-blue-200'
                    };

                    return (
                      <div
                        key={alert.id}
                        className={`p-4 rounded-lg border-l-4 ${severityColors[severity]}`}
                      >
                        <div className="flex justify-between items-start">
                          <div>
                            <p className="font-semibold">
                              {formatAlertReason(alert.reason)}
                            </p>
                            <p className="text-sm opacity-75 mt-1">
                              {new Date(alert.alert_time).toLocaleString()}
                            </p>
                          </div>
                          <span className="text-xs uppercase font-bold px-2 py-1 rounded">
                            {severity}
                          </span>
                        </div>
                      </div>
                    );
                  })
                )}
              </div>
            </div>
          </Card>
        </div>
      </div>
    </div>
  );
};

export default QuickMonitoring;
